{"path": "/tmp/sv-0f4c564aaf6742ceb8d58fbc1ad95a50/RecipeCommunity/Services/RecipeService.cs", "file_text": "using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out pizza dough on a floured surface.\n3. Spread crushed tomatoes evenly over the dough.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle with olive oil.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nOnion\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add tomatoes and simmer for 15 minutes.\n5. Stir in cream and cooked chicken.\n6. Simmer 10 more minutes and serve with rice.", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nTaco seasoning\nOnion", Steps = "1. Brown ground beef with diced onion.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm taco shells in the oven.\n4. Fill shells with seasoned beef.\n5. Top with lettuce, tomato, cheese, and sour cream.", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 4, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nPancetta\nEggs\nPecorino Romano\nBlack pepper\nSalt", Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with pancetta.\n5. Remove from heat, stir in egg mixture quickly.\n6. Serve immediately with extra cheese.", AverageRating = 4.7, RatingCount = 15 },
            new() { Id = 5, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nShrimp\nEgg\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar", Steps = "1. Soak rice noodles in warm water for 30 minutes.\n2. Stir-fry shrimp until pink, set aside.\n3. Scramble egg in the wok.\n4. Add noodles, fish sauce, tamarind, and sugar.\n5. Toss with shrimp, bean sprouts, and green onions.\n6. Serve with crushed peanuts and lime wedge.", AverageRating = 4.4, RatingCount = 10 },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve avocados and remove pits.\n2. Mash avocado to desired consistency.\n3. Stir in diced onion, tomato, and jalapeño.\n4. Add lime juice, cilantro, garlic, and salt.\n5. Taste and adjust seasoning.\n6. Serve immediately with tortilla chips.", AverageRating = 4.6, RatingCount = 18 },
            new() { Id = 7, Title = "Green Curry", Category = "Thai", Ingredients = "Coconut milk\nGreen curry paste\nChicken thigh\nBamboo shoots\nThai basil\nFish sauce\nSugar\nBell pepper\nEggplant", Steps = "1. Heat coconut cream in a pan until oil separates.\n2. Fry green curry paste for 2 minutes.\n3. Add sliced chicken and cook through.\n4. Pour in remaining coconut milk.\n5. Add vegetables and simmer 10 minutes.\n6. Season with fish sauce and sugar, garnish with Thai basil.", AverageRating = 4.3, RatingCount = 7 },
            new() { Id = 8, Title = "Butter Chicken", Category = "Indian", Ingredients = "Chicken thigh\nButter\nTomato puree\nHeavy cream\nGaram masala\nChili powder\nGinger\nGarlic\nFenugreek leaves", Steps = "1. Marinate chicken in yogurt and spices, grill until done.\n2. Melt butter and sauté ginger-garlic paste.\n3. Add tomato puree and cook for 10 minutes.\n4. Stir in cream, garam masala, and chili powder.\n5. Add grilled chicken pieces.\n6. Finish with crushed fenugreek leaves and serve with naan.", AverageRating = 4.9, RatingCount = 25 },
        };
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }

    public void Submit(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}
"}

