@using RecipeCommunity.Services
@inject RecipeService RecipeService
@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              title="@star star(s)">★</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>
<div class="rating-info">
    <span>Average: @Recipe.AverageRating.ToString("F1") / 5</span>
    <span>(@Recipe.RatingCount ratings)</span>
</div>

@code {
    [Parameter] public required Models.Recipe Recipe { get; set; }

    private int _selectedRating;
    private bool _submitted;

    private void Rate(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        RecipeService.AddRating(Recipe.Id, stars);
    }
}

@page "/"

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Recipe Community</PageTitle>

<div class="hero">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover and share delicious recipes from around the world</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="/category/@category" class="category-card">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <h3>@category</h3>
