@page "/recipe/{Id:int}"

@using RecipeCommunity.Services
@using RecipeCommunity.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <a href="/category/@Recipe.Category">@Recipe.Category</a> &rsaquo; <span>@Recipe.Title</span>
    </nav>

    <article class="recipe-detail">
        <h1>@Recipe.Title</h1>

        <StarRating Recipe="Recipe" />

        <section class="recipe-section">
            <h2>🧾 Ingredients</h2>
            <ul class="ingredients-list">
                @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>👨‍🍳 Steps</h2>
            <div class="steps-list">
                @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <p>@step</p>
                }
            </div>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer

@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="success-message">
        <h2>✅ Recipe Submitted!</h2>
        <p>Thank you for sharing "<strong>@_model.Title</strong>" with the community.</p>
        <a href="/">Back to Home</a>
    </div>
}
else
{
    <form @onsubmit="HandleSubmit" class="recipe-form">
        <div class="form-group">
            <label for="title">Recipe Title</label>
            <input id="title" @bind="_model.Title" placeholder="e.g., Grandma's Apple Pie" required />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <select id="category" @bind="_model.Category">
                <option value="">Select a category...</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </select>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <textarea id="ingredients" @bind="_model.Ingredients" rows="8"
                      placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" required></textarea>
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <textarea id="steps" @bind="_model.Steps" rows="8"
                      placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" required></textarea>
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </form>
}

@code {
    private RecipeSubmission _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.Title)) return;
        RecipeService.Submit(_model);
        _submitted = true;
    }
}

